        /// <summary>
        /// esta funcion busca el Label que se llame como la capa ingresada (IMPORTANTE!!! NO ES CASE SENSITIVE),
        /// y le aplica los estilos especificados, en este caso el color del relleno.
        /// </summary>
        /// <param name="svg"> svg a colorear</param>
        /// <param name="capa"> capa a rellenar, el estandar es "Outline"</param>
        /// <param name="color"> color el cual se cambiara el fill de los elementos de la capa seleccionad</param>
        /// <returns></returns>
        public static MarkupString SVGConColor(string svg, string capa, string color)
        {
            string buscar = $"inkscape:label=\"{capa}\"";
            string reemplazar = $"{buscar} class=\"svg-color-target\"";

            svg = svg.Replace(buscar, reemplazar);

            string style =
                "<style>" +
                ".svg-color-target path, " +
                ".svg-color-target rect, " +
                ".svg-color-target circle, " +
                ".svg-color-target polygon, " +
                ".svg-color-target ellipse {" +
                $"fill: {color} !important;" +
                "fill-opacity: 1 !important;" +
                "}" +
                "</style>";

            svg = svg.Replace("</svg>", style + "</svg>");

            return new MarkupString(svg);
        }
        /// <summary>
        /// para cosas como las estructuras de los vertices
        /// </summary>
        /// <param name="svg"></param>
        /// <param name="capa"></param>
        /// <param name="color"></param>
        /// <param name="uid"></param>
        /// <returns></returns>
        public static string SVGConColor_Multiples_instancias(string svg, string capa, string color, string uid = "")
        {
            string clase = $"svg-color-{uid}";

            string buscar = $"inkscape:label=\"{capa}\"";
            string reemplazar = $"{buscar} class=\"{clase}\"";

            svg = svg.Replace(buscar, reemplazar);

            string style =
                "<style>" +
                $".{clase} path, " +
                $".{clase} rect, " +
                $".{clase} circle, " +
                $".{clase} polygon, " +
                $".{clase} ellipse {{" +
                $"fill: {color} !important;" +
                "fill-opacity: 1 !important;" +
                "}" +
                "</style>";

            svg = svg.Replace("</svg>", style + "</svg>");

            return new string(svg);
        }

        public static MarkupString SVGOcultarCapa(string svg, string capa)
        {
            string buscar = $"inkscape:label=\"{capa}\"";

            if (svg.Contains(buscar))
            {
                svg = svg.Replace(
                    buscar,
                    $"{buscar} style=\"display:none;\""
                );
            }

            return new MarkupString(svg);
        }

        public static MarkupString RecursoIcono(ResourceType recurso)
        {
            return recurso switch
            {
                ResourceType.Wood => new MarkupString(SvgIcons.SVG_Wood),
                ResourceType.Sheep => new MarkupString(SvgIcons.SVG_Sheep),
                _ => new MarkupString(SVG_Missing_Texture)
            };
        }
    }
